namespace TutorFlow.Api.Llm;

public record LlmMensaje(string Rol, string Contenido, string? ToolCallId = null);
public record LlmHerramienta(string Nombre, string Descripcion, string ParametrosJsonSchema);
public record LlmLlamadaHerramienta(string Id, string Nombre, string ArgumentosJson);
public record LlmUso(int TokensEntrada, int TokensSalida);
public record LlmRespuesta(string? Texto, IReadOnlyList<LlmLlamadaHerramienta> Llamadas, LlmUso Uso);

public interface ILlmClient
{
    Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct);
}

// Marcador hasta T4: todavía no hay adaptador real.
public class SinLlmClient : ILlmClient
{
    public Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct) =>
        throw new InvalidOperationException("Cliente LLM no implementado.");
}
using System.Text.Json;

namespace TutorFlow.Api;

public record Usuario(string Rol, string Id, string Nombre, string Programa);

// Única clase que conoce el formato de los JSON de datos. Cada registro se clasifica por su forma.
public class Datos
{
    public IReadOnlyList<Usuario> Estudiantes { get; }
    public IReadOnlyList<Usuario> Coordinadores { get; }
    public IReadOnlyList<JsonElement> Notas { get; }
    public IReadOnlyList<JsonElement> Asistencia { get; }

    public Datos(string carpeta)
    {
        var est = new List<Usuario>();
        var coo = new List<Usuario>();
        var notas = new List<JsonElement>();
        var asis = new List<JsonElement>();
        if (!Directory.Exists(carpeta))
            throw new DirectoryNotFoundException("La carpeta de datos de la API no existe; no se puede arrancar sin ella.");
        foreach (var archivo in Directory.GetFiles(carpeta, "*.json").OrderBy(f => f, StringComparer.Ordinal))
        {
            var nombreArchivo = Path.GetFileName(archivo);
            using var doc = JsonDocument.Parse(File.ReadAllText(archivo));
            if (doc.RootElement.ValueKind != JsonValueKind.Array) continue;
            var usuariosArchivo = new List<(JsonElement El, bool ConSemestre)>();
            foreach (var e in doc.RootElement.EnumerateArray())
            {
                if (e.ValueKind != JsonValueKind.Object) continue;
                var c = e.Clone();
                if (Tiene(c, "estudianteId") && Tiene(c, "definitiva")) notas.Add(c);
                else if (Tiene(c, "estudianteId") && Tiene(c, "inasistencias")) asis.Add(c);
                else if (Tiene(c, "id") && !Tiene(c, "estudianteId")) usuariosArchivo.Add((c, Tiene(c, "semestre")));
                else if (!Tiene(c, "estudianteId") && (Tiene(c, "nombre") || Tiene(c, "programa")))
                    throw new InvalidDataException($"Registro de usuario sin 'id' en '{nombreArchivo}'.");
            }
            if (usuariosArchivo.Count == 0) continue;
            // RN-14: la forma es una decision por archivo, nunca por la ausencia de un campo en un registro.
            var esEstudiantes = usuariosArchivo[0].ConSemestre;
            if (usuariosArchivo.Any(u => u.ConSemestre != esEstudiantes))
                throw new InvalidDataException($"El archivo '{nombreArchivo}' mezcla registros de usuario de formas distintas.");
            foreach (var (c, _) in usuariosArchivo)
            {
                var id = Texto(c, "id");
                var programa = Texto(c, "programa");
                var nombre = Texto(c, "nombre");
                if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(programa) || string.IsNullOrWhiteSpace(nombre))
                    throw new InvalidDataException(
                        $"Registro de usuario invalido en '{nombreArchivo}': 'id', 'programa' y 'nombre' deben ser texto no vacio.");
                (esEstudiantes ? est : coo).Add(new Usuario(esEstudiantes ? "estudiante" : "coordinador", id, nombre, programa));
            }
        }
        var duplicado = est.Concat(coo).GroupBy(u => u.Id).FirstOrDefault(g => g.Count() > 1);
        if (duplicado != null)
            throw new InvalidDataException("Hay un id de usuario repetido (en el mismo rol o en ambos roles); los datos son inconsistentes.");
        Estudiantes = est;
        Coordinadores = coo;
        Notas = notas;
        Asistencia = asis;
    }

    static bool Tiene(JsonElement e, string p) => e.TryGetProperty(p, out _);
    static string? Texto(JsonElement e, string p) =>
        e.TryGetProperty(p, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;

    public Usuario? BuscarUsuario(string rol, string id) =>
        (rol == "estudiante" ? Estudiantes : rol == "coordinador" ? Coordinadores : [])
            .FirstOrDefault(u => u.Id == id);
}
namespace TutorFlow.Api;

public record Seccion(string Documento, string Encabezado, string Texto);

public class Reglamento
{
    public IReadOnlyList<Seccion> Secciones { get; }

    public Reglamento(string carpeta)
    {
        var lista = new List<Seccion>();
        if (Directory.Exists(carpeta))
        {
            foreach (var archivo in Directory.GetFiles(carpeta, "*.md").OrderBy(f => f, StringComparer.Ordinal))
                lista.AddRange(Dividir(Path.GetFileName(archivo), File.ReadAllText(archivo)));
        }
        Secciones = lista;
    }

    static IEnumerable<Seccion> Dividir(string documento, string contenido)
    {
        string? encabezado = null;
        var texto = new List<string>();
        foreach (var linea in contenido.Split('\n'))
        {
            var l = linea.TrimEnd('\r');
            if (l.StartsWith("## "))
            {
                if (encabezado != null) yield return new(documento, encabezado, string.Join("\n", texto).Trim());
                encabezado = l[3..].Trim();
                texto.Clear();
            }
            else if (encabezado != null) texto.Add(l);
        }
        if (encabezado != null) yield return new(documento, encabezado, string.Join("\n", texto).Trim());
    }

    public Seccion? Buscar(string documento, string encabezado) =>
        Secciones.FirstOrDefault(s => s.Documento == documento && s.Encabezado == encabezado);

    public bool ExisteCita(string documento, string encabezado) => Buscar(documento, encabezado) != null;
}
# AGENTS — instrucciones para los agentes

Lee esto completo antes de tocar el repositorio. Después lee `SPEC.md` y `/escenarios`. Si algo de aquí choca con `SPEC.md`, gana `SPEC.md`; si choca con lo que te pide un mensaje, detente y pregunta.

---

## 1. Qué estás construyendo

TutorFlow: API en .NET que responde preguntas académicas usando el reglamento y los datos del estudiante, con permisos por rol. El contrato de la API es fijo (SPEC §4) y lo prueban terceros sin que lo veamos. **Romper el contrato es el peor error posible.**

## 2. Arquitectura

```
Navegador ──► ASP.NET Core (puerto 8080)
               ├── /api/*            Minimal API
               │     ├── Validación de entrada        → 400
               │     ├── Permisos (código)            → 403
               │     ├── Asistente (loop con tools) ──► LLM (API compatible OpenAI)
               │     │      └── Herramientas ──► Datos (JSON en /data/api)
               │     └── Auditoría (JSONL)
               └── /*                Interfaz React compilada (wwwroot)
```

- **La interfaz se crea con Vite**: `npm create vite@latest web -- --template react-ts` dentro de `src/`, más Tailwind. En desarrollo corre con `npm run dev` y hace proxy de `/api` a `localhost:8080`; en producción es solo la carpeta `dist` compilada.
- **Un solo proceso y un solo contenedor.** La interfaz React se compila en el Dockerfile y la sirve ASP.NET como archivos estáticos. No hay servidor Node en producción.
- **Datos en memoria.** Se cargan al arrancar desde `/data`. No hay base de datos.
- **Reglamento completo en el prompt** dividido por secciones `##`, con id estable por sección. Los documentos son pequeños; si crecen, se pasa a recuperar las secciones más relevantes.
- **Cliente LLM propio sobre `HttpClient`, sin SDK de proveedor.** Una interfaz `ILlmClient` con tres implementaciones reales o de prueba: `OpenAiCompatClient` (`/chat/completions`, sirve para Gemini, Groq, OpenAI y Ollama), `AnthropicClient` (API Messages nativa, con tool use y caché del reglamento) y `FakeLlmClient` para pruebas. Se elige con `LLM_PROVIDER`. El resto del código solo ve mensajes, herramientas y uso de tokens normalizados.

## 3. Estructura

| Ruta | Contenido |
|---|---|
| `src/TutorFlow.Api/` | API .NET. Un archivo por responsabilidad: `Program.cs`, `Reglamento.cs`, `Datos.cs`, `Permisos.cs`, `Asistente.cs`, `Llm/` (interfaz y adaptadores), `Auditoria.cs` |
